def coding_challenge(strArr):
    n = len(strArr)
    best = 0
    for K in range(1, n + 1):
        top_bottom = all(strArr[0][j] == "B" and strArr[K - 1][j] == "B" for j in range(K))
        left_right = all(strArr[i][0] == "B" and strArr[i][K - 1] == "B" for i in range(K))
        if top_bottom and left_right:
            best = K
    return f"0 0 {best}"

class Solution {
    static String codingChallenge(String[] strArr) {
        int n = strArr.length, best = 0;
        for (int K = 1; K <= n; K++) {
            boolean ok = true;
            for (int j = 0; j < K && ok; j++) {
                if (strArr[0].charAt(j) != 'B') ok = false;
                if (strArr[K - 1].charAt(j) != 'B') ok = false;
            }
            for (int i = 0; i < K && ok; i++) {
                if (strArr[i].charAt(0) != 'B') ok = false;
                if (strArr[i].charAt(K - 1) != 'B') ok = false;
            }
            if (ok) best = K;
        }
        return "0 0 " + best;
    }
}

